setIcons();try{setTheme(localStorage.getItem('arus-theme')==='dark');}catch{}
function closeLogin(){const dialog=$('#loginDialog');if(dialog.open)dialog.close();document.documentElement.classList.remove('login-modal-open');}
function openLogin(){const dialog=$('#loginDialog');if(!dialog.open)dialog.showModal();document.documentElement.classList.add('login-modal-open');$('#username').focus();}
