$('#showPassword').addEventListener('click',()=>{const p=$('#password'),show=p.type==='password';p.type=show?'text':'password';$('#showPassword').textContent=show?'Sembunyikan':'Lihat';$('#showPassword').setAttribute('aria-label',show?'Sembunyikan kata sandi':'Tampilkan kata sandi');});
$('#useProjectAccount').addEventListener('click',()=>{$('#username').value='mahasiswa';$('#password').value='Energi2024!';$('#loginError').hidden=true;$('#loginSubmit').focus();});
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').hidden=true;$('#loginSubmit').disabled=true;try{const session=await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#username').value.trim(),password:$('#password').value})});await enterApp(session);}catch(err){$('#loginError').textContent=err.message;$('#loginError').hidden=false;}finally{$('#loginSubmit').disabled=false;}});
$('#logout').addEventListener('click',()=>{window.location='/keluar';});
$('#themeToggle').addEventListener('click',()=>setTheme(!document.documentElement.classList.contains('dark')));
$('#regionFilter').addEventListener('change',e=>{state.region=e.target.value;state.province='';syncProvinceOptions();render();});
$('#provinceFilter').addEventListener('change',e=>{state.province=e.target.value;render();});
$('#resetFilters').addEventListener('click',()=>{state.region='';state.province='';state.search='';state.mapZoom=1;$('#regionFilter').value='';syncProvinceOptions();render();toast('Filter direset ke seluruh Indonesia.');});
$('#exportTop').addEventListener('click',()=>exportCsv(state.page==='compare'?state.compare.map(c=>state.data.provinces.find(r=>r.code===c)):state.page==='explore'?tableRows():rows(),state.page));
$('#menuToggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#scrim').hidden=!open;$('#menuToggle').setAttribute('aria-expanded',String(open));});
$('#scrim').addEventListener('click',closeMenu);
$('#closeDetail').addEventListener('click',()=>$('#detailDialog').close());
$('#detailDialog').addEventListener('click',e=>{if(e.target===$('#detailDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){navigate(page.dataset.page);return;}const el=e.target.closest('[data-detail]');if(el)detail(el.dataset.detail);});
function placeTip(e){const t=$('#tooltip');if(t.hidden)return;const box=t.getBoundingClientRect();t.style.left=Math.max(8,Math.min(e.clientX+15,innerWidth-box.width-10))+'px';t.style.top=Math.max(8,Math.min(e.clientY+16,innerHeight-box.height-10))+'px';}
document.addEventListener('pointerover',e=>{const tip=e.target.closest('[data-tip]');if(!tip){$('#tooltip').hidden=true;return;}const [title,...text]=tip.dataset.tip.split('|');$('#tooltip').innerHTML=`<strong>${esc(title)}</strong>${esc(text.join(' '))}`;$('#tooltip').hidden=false;placeTip(e);});
document.addEventListener('pointermove',placeTip);document.addEventListener('scroll',()=>$('#tooltip').hidden=true,true);
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p==='sources'&&!$('#app').hidden){navigate('overview');return;}if(state.data&&pageText[p]){state.page=p;render();}});

document.addEventListener('click',e=>{
  const selected=e.target.closest('[data-map-select]');
  if(selected){focusProvince(selected.dataset.mapSelect);return;}
  const clear=e.target.closest('[data-clear-map]');
  if(clear){state.province='';state.region='';state.mapZoom=1;$('#regionFilter').value='';syncProvinceOptions();render();return;}
  const compareButton=e.target.closest('[data-add-compare]');
  if(compareButton){const code=compareButton.dataset.addCompare;if(!state.compare.includes(code))state.compare[0]=code;navigate('compare');}
});
document.addEventListener('keydown',e=>{
  if(e.key!=='Enter'&&e.key!==' ')return;
  const el=e.target.closest('.map-province,.plot-point,.gap-item');if(!el)return;e.preventDefault();
  if(el.dataset.mapSelect){const code=el.dataset.mapSelect;focusProvince(code);document.querySelector('.map-province[data-map-select="'+code+'"]')?.focus();}
  else if(el.dataset.detail)detail(el.dataset.detail);
});

(async()=>{try{await enterApp(await api('/api/session'));}catch(err){console.error(err);const b=document.getElementById('boot');if(b){const p=b.querySelector('p');if(p)p.textContent='Data belum bisa dimuat. Pastikan ETL sudah dijalankan lalu muat ulang halaman.';}}})();
